// Tempo in Ma (milioni di anni fa, positivi). Coordinate ATTUALI (lat, lon).
// Scala del tempo: ICS International Chronostratigraphic Chart (v2024/12, confermata in v2026/06).
// =====================================================================

const ERAS = [
  // ---------- EONI ----------
  {id:"adeano", name:"Adeano", level:"eone", from:4567, to:4031, color:"#AE027E",
   text:"L'eone «infernale»: la Terra appena nata è bombardata da asteroidi, coperta da un oceano di magma e poi da una crosta sottile. Si forma la Luna e, già 4,4 miliardi di anni fa, compaiono i primi oceani. Non restano rocce di quest'epoca, solo minuscoli cristalli di zircone."},
  {id:"archeano", name:"Archeano", level:"eone", from:4031, to:2500, color:"#F0047F",
   text:"Nascono i primi nuclei di continenti e un'atmosfera senza ossigeno, ricca di anidride carbonica e metano. La vita è solo microbica: batteri e archei costruiscono le stromatoliti. Verso la fine i cianobatteri iniziano a produrre ossigeno con la fotosintesi."},
  {id:"proterozoico", name:"Proterozoico", level:"eone", from:2500, to:538.8, color:"#F73563",
   text:"L'ossigeno si accumula nell'aria (Grande Ossidazione) e la Terra attraversa glaciazioni globali. Compaiono le cellule complesse (eucarioti), la riproduzione sessuale e i primi organismi pluricellulari. Alla fine vivono nei mari i misteriosi organismi di Ediacara, tra i primi animali."},
  {id:"fanerozoico", name:"Fanerozoico", level:"eone", from:538.8, to:0, color:"#9AD9DD",
   text:"L'eone della «vita visibile»: animali con conchiglie e scheletri lasciano abbondanti fossili. Piante e animali conquistano le terre emerse, i continenti si uniscono nella Pangea e poi si separano. Cinque grandi estinzioni di massa ridisegnano più volte la storia della vita."},

  // ---------- ERE ----------
  {id:"eoarcheano", name:"Eoarcheano", level:"era", from:4031, to:3600, color:"#DA037F",
   text:"Risalgono a quest'era le rocce più antiche conservate, come gli gneiss di Acasta (Canada) e le rocce di Isua (Groenlandia). Il bombardamento di meteoriti diminuisce e gli oceani diventano stabili. Alcuni ricercatori vi vedono i primi indizi chimici di vita, ancora molto discussi."},
  {id:"paleoarcheano", name:"Paleoarcheano", level:"era", from:3600, to:3200, color:"#F444A9",
   text:"Si formano i primi cratoni, i «semi» dei continenti, come Kaapvaal (Sudafrica) e Pilbara (Australia). Nelle acque basse crescono le stromatoliti, le più antiche tracce di vita ben riconosciute (3,48 miliardi di anni). Il cielo è privo di ossigeno e il Sole è più debole di oggi."},
  {id:"mesoarcheano", name:"Mesoarcheano", level:"era", from:3200, to:2800, color:"#F768A9",
   text:"Probabilmente comincia una tettonica a placche simile a quella attuale, anche se i geologi ne discutono. Compaiono forse le prime glaciazioni (Pongola, 2,9 miliardi di anni fa). I tappeti microbici si diffondono e forse esistono già i primi cianobatteri."},
  {id:"neoarcheano", name:"Neoarcheano", level:"era", from:2800, to:2500, color:"#F99BC1",
   text:"I continenti crescono rapidamente e si saldano in grandi blocchi. I cianobatteri producono ossigeno, che però viene subito consumato da ferro e gas vulcanici: si depositano enormi formazioni di ferro a bande. Compaiono i primi «soffi» di ossigeno nell'atmosfera."},
  {id:"paleoproterozoico", name:"Paleoproterozoico", level:"era", from:2500, to:1600, color:"#F74370",
   text:"È l'era della Grande Ossidazione: l'ossigeno entra stabilmente nell'atmosfera e la Terra attraversa la glaciazione uroniana. Grandi asteroidi colpiscono Vredefort e Sudbury e si forma il supercontinente Columbia (Nuna). Compaiono le prime cellule eucariote certe."},
  {id:"mesoproterozoico", name:"Mesoproterozoico", level:"era", from:1600, to:1000, color:"#FDB462",
   text:"Un lungo periodo di clima stabile, detto scherzosamente «il miliardo noioso». In realtà gli eucarioti si diversificano: compaiono le alghe rosse pluricellulari con riproduzione sessuale (Bangiomorpha) e le prime alghe verdi. Verso la fine si forma il supercontinente Rodinia."},
  {id:"neoproterozoico", name:"Neoproterozoico", level:"era", from:1000, to:538.8, color:"#FEB342",
   text:"Rodinia si spezza e la Terra si congela quasi del tutto almeno due volte («Terra a palla di neve»). Dopo i ghiacci, l'ossigeno aumenta e nei mari compaiono i primi grandi organismi pluricellulari, la biota di Ediacara. Alla fine nascono gli animali con gusci e le prime tracce di movimento."},
  {id:"paleozoico", name:"Paleozoico", level:"era", from:538.8, to:251.902, color:"#99C08D",
   text:"L'era della «vita antica»: si apre con l'esplosione cambriana e la comparsa di quasi tutti i grandi gruppi animali. Piante, artropodi e vertebrati conquistano la terraferma e nascono le foreste. Si chiude con la Pangea e con la più grave estinzione di sempre."},
  {id:"mesozoico", name:"Mesozoico", level:"era", from:251.902, to:66.0, color:"#67C5CA",
   text:"L'era «di mezzo», detta anche età dei rettili: dominano dinosauri, pterosauri e grandi rettili marini. La Pangea si divide, si aprono l'Atlantico e l'Oceano Indiano. Compaiono mammiferi, uccelli e piante con fiori; l'era finisce con l'asteroide di Chicxulub."},
  {id:"cenozoico", name:"Cenozoico", level:"era", from:66.0, to:0, color:"#F2F91D",
   text:"L'era «nuova», l'età dei mammiferi. I continenti raggiungono quasi la posizione attuale, nascono Alpi e Himalaya e il clima si raffredda fino alle glaciazioni. Si diffondono le praterie, i mammiferi diventano giganti e infine compaiono gli esseri umani."},

  // ---------- PERIODI ----------
  {id:"tonico", name:"Tonico", level:"periodo", from:1000, to:720, color:"#FEBF4E",
   text:"Il supercontinente Rodinia è unito e poi comincia a spezzarsi. Nei mari si diffondono alghe e protisti con gusci microscopici; forse compaiono le prime spugne, ma la prova è discussa. Il clima è ancora mite prima delle grandi glaciazioni."},
  {id:"criogeniano", name:"Criogeniano", level:"periodo", from:720, to:635, color:"#FECC5C",
   text:"Il periodo del «freddo»: due glaciazioni globali, la sturtiana (circa 717–660 milioni di anni fa) e la marinoana (circa 650–635), coprono di ghiaccio quasi tutta la Terra, anche all'equatore. La vita microbica sopravvive in zone libere dai ghiacci o presso sorgenti calde. Le prime tracce chimiche attribuite a spugne risalgono forse a questo periodo."},
  {id:"ediacarano", name:"Ediacarano", level:"periodo", from:635, to:538.8, color:"#FED96A",
   text:"Dopo il disgelo l'ossigeno aumenta e nei fondali compaiono i primi organismi pluricellulari grandi: le forme a fronda di Mistaken Point, Dickinsonia, Kimberella. Verso la fine nascono i primi animali con gusci (Cloudina) e le prime piste di animali che si muovono."},
  {id:"cambriano", name:"Cambriano", level:"periodo", from:538.8, to:486.85, color:"#7FA056",
   text:"In pochi milioni di anni compaiono quasi tutti i grandi gruppi di animali: è l'esplosione cambriana. I mari caldi ospitano trilobiti, predatori come Anomalocaris e i primi vertebrati; giacimenti eccezionali come Chengjiang e Burgess conservano anche le parti molli. Le terre emerse sono ancora spoglie."},
  {id:"ordoviciano", name:"Ordoviciano", level:"periodo", from:486.85, to:443.1, color:"#009270",
   text:"I mari sono alti e caldi e la vita marina si diversifica enormemente (GOBE): coralli, brachiopodi, nautiloidi giganti, trilobiti di ogni forma. Le prime piante simili a muschi colonizzano le coste. Il periodo si chiude con una glaciazione e la prima grande estinzione."},
  {id:"siluriano", name:"Siluriano", level:"periodo", from:443.1, to:419.62, color:"#B3E1B6",
   text:"Il clima torna mite e si formano grandi barriere coralline. Compaiono le prime piante vascolari (Cooksonia) e i primi animali terrestri, come i millepiedi. Nei mari si diffondono i pesci con mascelle e gli euripteridi, «scorpioni di mare»."},
  {id:"devoniano", name:"Devoniano", level:"periodo", from:419.62, to:358.86, color:"#CB8C37",
   text:"L'età dei pesci: placodermi corazzati come Dunkleosteus, squali primitivi e pesci con pinne carnose. Sulle terre emerse nascono le prime foreste e i primi tetrapodi escono dall'acqua. Il periodo termina con una serie di crisi ambientali e una grande estinzione."},
  {id:"carbonifero", name:"Carbonifero", level:"periodo", from:358.86, to:298.9, color:"#67A599",
   text:"Paludi immense, coperte da licopodi alti 30 metri e da equiseti giganti, formano gli strati di carbone. L'ossigeno nell'aria raggiunge forse il 30% (le stime vanno dal 25 al 35%) e gli artropodi diventano giganti, come Meganeura e Arthropleura. Compaiono i primi amnioti, antenati di rettili, uccelli e mammiferi."},
  {id:"permiano", name:"Permiano", level:"periodo", from:298.9, to:251.902, color:"#F04028",
   text:"I continenti formano la Pangea e al suo interno si estendono vasti deserti. Dominano i sinapsidi, come Dimetrodon e poi i terapsidi, parenti dei mammiferi; a sud crescono le foreste a Glossopteris. Il periodo termina con la più grande estinzione della storia, legata alle eruzioni siberiane."},
  {id:"triassico", name:"Triassico", level:"periodo", from:251.902, to:201.4, color:"#812B92",
   text:"La vita si riprende lentamente in un mondo caldo e arido, con la Pangea ancora unita. Compaiono dinosauri, pterosauri, coccodrilli, tartarughe, ittiosauri e i primi mammiferi. Un clima più umido nel Carnico favorisce i dinosauri; il periodo finisce con un'estinzione di massa."},
  {id:"giurassico", name:"Giurassico", level:"periodo", from:201.4, to:143.1, color:"#34B2C9",
   text:"La Pangea si divide e si apre l'Atlantico centrale; il clima è caldo e umido, con foreste di conifere, cicadee e felci. I dinosauri dominano: giganti sauropodi, stegosauri, allosauri. Nei mari nuotano plesiosauri, ittiosauri e ammoniti; compaiono i primi uccelli."},
  {id:"cretaceo", name:"Cretaceo", level:"periodo", from:143.1, to:66.0, color:"#7FC64E",
   text:"I continenti continuano a separarsi e il livello del mare è altissimo: mari interni dividono il Nord America. Nascono e si diffondono le piante con fiori, insieme a insetti impollinatori. Vivono tirannosauri, triceratopi e mosasauri, fino all'impatto di Chicxulub."},
  {id:"paleogene", name:"Paleogene", level:"periodo", from:66.0, to:23.04, color:"#FD9A52",
   text:"Dopo l'estinzione dei dinosauri i mammiferi si diversificano rapidamente. Il clima, caldissimo nell'Eocene, poi si raffredda e l'Antartide si copre di ghiaccio. Le balene tornano al mare e l'India si scontra con l'Asia."},
  {id:"neogene", name:"Neogene", level:"periodo", from:23.04, to:2.58, color:"#FFE619",
   text:"Il clima diventa più fresco e secco: si espandono le praterie e con esse cavalli, antilopi e predatori veloci. Il Mediterraneo si prosciuga nella crisi del Messiniano e si chiude l'istmo di Panama. In Africa compaiono i primi ominini."},
  {id:"quaternario", name:"Quaternario", level:"periodo", from:2.58, to:0, color:"#F9F97F",
   text:"È il periodo delle glaciazioni: grandi calotte avanzano e si ritirano decine di volte. Vivono mammut, rinoceronti lanosi e felini dai denti a sciabola. Il genere Homo si diffonde in tutto il mondo e Homo sapiens arriva in ogni continente tranne l'Antartide."},

  // ---------- EPOCHE DEL CENOZOICO ----------
  {id:"paleocene", name:"Paleocene", level:"epoca", from:66.0, to:56.0, color:"#FDA75F",
   text:"Il mondo si riprende dall'impatto di Chicxulub: in poche centinaia di migliaia di anni i mammiferi crescono di taglia. Compaiono foreste pluviali moderne, abitate da serpenti giganti come Titanoboa. Il clima è caldo e senza ghiacci polari."},
  {id:"eocene", name:"Eocene", level:"epoca", from:56.0, to:33.9, color:"#FDB46C",
   text:"Si apre con un improvviso riscaldamento (PETM) e foreste che arrivano fino ai poli. Compaiono primati, cavalli primitivi e i primi cetacei, che dalla terraferma tornano al mare. Alla fine il clima si raffredda bruscamente e l'Antartide si copre di ghiaccio."},
  {id:"oligocene", name:"Oligocene", level:"epoca", from:33.9, to:23.04, color:"#FDC07A",
   text:"Il clima è più fresco e asciutto e le foreste lasciano spazio a boschi aperti. Vivono i più grandi mammiferi terrestri di sempre, come Paraceratherium. In Europa molte specie antiche sono sostituite da immigrati asiatici (Grande Coupure)."},
  {id:"miocene", name:"Miocene", level:"epoca", from:23.04, to:5.333, color:"#FFFF00",
   text:"Un caldo iniziale lascia spazio a un raffreddamento: si espandono praterie e savane. Si diversificano le scimmie antropomorfe in Africa ed Eurasia e nei mari nuota il megalodonte. Alla fine il Mediterraneo si prosciuga (crisi di salinità del Messiniano)."},
  {id:"pliocene", name:"Pliocene", level:"epoca", from:5.333, to:2.58, color:"#FFFF99",
   text:"L'Atlantico riempie di nuovo il Mediterraneo e il clima è un po' più caldo di oggi. In Africa camminano gli australopiteci, come Lucy. Si chiude l'istmo di Panama e animali del Nord e del Sud America si scambiano i continenti."},
  {id:"pleistocene", name:"Pleistocene", level:"epoca", from:2.58, to:0.0117, color:"#FFF2AE",
   text:"L'epoca delle glaciazioni, con fasi fredde e calde che si alternano. Prospera la megafauna: mammut, bradipi giganti, diprotodonti. Compaiono Homo erectus, i Neanderthal e Homo sapiens, che alla fine popola tutti i continenti."},
  {id:"olocene", name:"Olocene", level:"epoca", from:0.0117, to:0, color:"#FEF2E0",
   text:"È l'epoca in cui viviamo, iniziata 11.700 anni fa con la fine dell'ultima glaciazione. Il clima stabile permette la nascita dell'agricoltura, delle città e della scrittura. Le attività umane modificano sempre di più il pianeta, causando una nuova crisi della biodiversità."}
];

